MATERIALS = ["metal", "polymer", "ceramic", "composite", "elastomer", "wood"]

async def evaluate_material(image, material):
    r = await async_client.messages.create(
        model="claude-sonnet-4-6", max_tokens=300,
        messages=[{"role": "user", "content": [
            image,
            {"type": "text", "text": f"Evaluate this part specifically for {material}: strength, cost, manufacturability."}
        ]}],
    )
    return {"material": material, "analysis": r.content[0].text}

async def recommend_material(image):
    evaluations = await asyncio.gather(*[evaluate_material(image, m) for m in MATERIALS])
    # aggregation step: a final request compares all evaluations
    return ask_claude(f"Given these per-material evaluations, recommend the best option:\n{evaluations}")

def generate_contract(client_brief):
    requirements = ask_claude(f"Extract the key requirements from: {client_brief}")

    if "missing" in requirements.lower():  # gate
        return {"error": "incomplete requirements, ask the client for more info"}

    draft = ask_claude(f"Draft a contract with these requirements: {requirements}")
    final_version = ask_claude(f"Review and polish the legal language of: {draft}")
    return {"contract": final_version}

PROMPTS_BY_CATEGORY = {
    "technical": ("claude-opus-4-8", "You are level-2 technical support..."),
    "billing": ("claude-sonnet-4-6", "You are billing support..."),
    "faq": ("claude-haiku-4-5-20251001", "Answer frequently asked questions briefly..."),
}

def route_and_respond(message):
    # cheap model for classification
    category = ask_claude(
        f"Classify as technical/billing/faq (one word): {message}",
        model="claude-haiku-4-5-20251001",
    ).strip()

    model, system_prompt = PROMPTS_BY_CATEGORY.get(category, PROMPTS_BY_CATEGORY["faq"])
    return ask_claude(message, model=model, system=system_prompt)

def generate_with_evaluation(task, criteria, max_attempts=3):
    feedback = ""
    for attempt in range(max_attempts):
        draft = ask_claude(f"{task}\n\nFeedback from previous iteration: {feedback}")
        evaluation = ask_claude(
            f"Evaluate whether this text meets these criteria: {criteria}\n\nText: {draft}\n\n"
            "If it meets everything, respond exactly 'OK'. If not, return specific, actionable feedback."
        )
        if evaluation.strip() == "OK":
            return draft
        feedback = evaluation
    return draft  # returns the last attempt even if it wasn't approved

