def compact_if_needed(messages, token_threshold=50000, keep_last=4):
    if estimate_tokens(messages) < token_threshold:
        return messages

    old_history = messages[:-keep_last]
    summary = ask_claude(
        f"Summarize in a few paragraphs what's relevant from this to continue the task:\n{old_history}"
    )
    return [
        {"role": "user", "content": f"Summary of progress so far:\n{summary}"}
    ] + messages[-keep_last:]

