import logging

ACTIONS_REQUIRING_APPROVAL = {"send_email", "charge_card", "delete_record"}

def execute_with_approval(tool_use_block):
    if tool_use_block.name in ACTIONS_REQUIRING_APPROVAL:
        approved = input(f"Approve executing {tool_use_block.name} with {tool_use_block.input}? (y/n) ")
        if approved.lower() != "y":
            return "Action cancelled by the user"
    return execute_tool(tool_use_block.name, tool_use_block.input)

