    for i in range(max_iterations):
        response = client.messages.create(
            model="claude-sonnet-4-6", max_tokens=1500, tools=tools, messages=messages
        )
        logging.info(
            "iteration=%d stop_reason=%s output_tokens=%d",
            i, response.stop_reason, response.usage.output_tokens,
        )
        for block in response.content:
            if block.type == "tool_use":
                logging.info("tool=%s input=%s", block.name, block.input)
        messages.append({"role": "assistant", "content": response.content})
